sys_ui_page.client_script:
function onLoad() {
    var urlParams = new URLSearchParams(window.location.search);
    var eventId = urlParams.get('sysparm_event_id');

    var ga = new GlideAjax('EventDashboardUtils');
    ga.addParam('sysparm_name', 'getEventDetails');
    ga.addParam('sysparm_eventId', eventId);

    ga.getXMLAnswer(function(response) {
        var data = JSON.parse(response);
        var detailsDiv = document.getElementById('eventDetails');

        var html = '<h3>Tasks</h3><ul>';
        data.tasks.forEach(function(task) {
            html += '<li>' + task.name + ' - ' + task.status + '</li>';
        });
        html += '</ul>';

        html += '<h3>Attendees</h3><ul>';
        data.attendees.forEach(function(att) {
            html += '<li>' + att.name + '</li>';
        });
        html += '</ul>';

        html += '<h3>Vendors</h3><ul>';
        data.vendors.forEach(function(vendor) {
            html += '<li>' + vendor.name + '</li>';
        });
        html += '</ul>';

        html += '<h3>Budget</h3>';
        html += '<p>Total: ' + data.budget.total + ', Spent: ' + data.budget.spent + ', Remaining: ' + data.budget.remaining + ', Status: ' + data.budget.status + '</p>';

        html += '<h3>Feedback</h3><ul>';
        data.feedback.forEach(function(fb) {
            html += '<li>Rating: ' + fb.rating + ' - Comments: ' + fb.comments + '</li>';
        });
        html += '</ul>';

        detailsDiv.innerHTML = html;
    });
}
